<?php
require_once ROOT_PATH.'core/Controller.php';
require_once APP_PATH.'Models/Loan.php';
require_once APP_PATH.'Models/Notification.php';
class LoansController extends Controller {
 private $loans; private $notes;
 public function __construct(){$this->loans=new Loan();$this->notes=new Notification();}
 private function employee(){Auth::requireSelfService();return Auth::employeeId();}
 private function admin(){Auth::requireRole(['Super Admin','HR Manager']);}
 private function post($admin=false){$admin?$this->admin():Auth::requireSelfService();Auth::requireMethod('POST');if(!verify_csrf_token($_POST['csrf_token']??''))$this->json('error','Invalid CSRF token.',[],403);}
 private function upload(){if(empty($_FILES['requirement']['name']))return [null,null];$f=$_FILES['requirement'];if($f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Requirement upload failed.');if($f['size']>5*1024*1024)throw new RuntimeException('Requirement file must not exceed 5 MB.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$allowed=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!isset($allowed[$ext])||$allowed[$ext]!==$mime)throw new RuntimeException('Only PDF, JPG and PNG requirements are allowed.');$dir=ROOT_PATH.'uploads/loans';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Unable to prepare loan storage.');$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Unable to store requirement.');return ['uploads/loans/'.$name,basename($f['name'])];}
 public function apply(){ $this->post();$emp=$this->employee();$file=null;try{[$file,$original]=$this->upload();$id=$this->loans->apply((int)($_POST['loan_program_id']??0),$emp,(float)($_POST['requested_amount']??0),(int)($_POST['term_months']??0),sanitize_input($_POST['application_notes']??''),$file,$original);$loan=$this->loans->details($id);$this->notes->createForEmployee($emp,'Loan application submitted','Your '.$loan['loan_type'].' application was submitted.','info','index.php?page=benefits_loans','loans',$id);$this->notes->createForAdmins('New loan application','Employee ID '.$emp.' submitted a '.$loan['loan_type'].' loan application.','info','index.php?page=benefits_loans','loans',$id);AuditLogger::log('LOAN_APPLICATION_SUBMITTED','Loans Management','Loan ID '.$id.' submitted by Employee ID '.$emp);$this->json('success','Loan application submitted.',['id'=>$id]);}catch(Throwable $e){if($file&&is_file(ROOT_PATH.$file))unlink(ROOT_PATH.$file);$this->json('error',$e->getMessage(),[],422);}}
 public function resubmit(){ $this->post();$emp=$this->employee();$id=(int)($_POST['loan_id']??0);$loan=$this->loans->details($id,$emp);if(!$loan||$loan['status']!=='Returned')$this->json('error','Returned loan application not found.',[],404);$amount=(float)($_POST['requested_amount']??0);$term=(int)($_POST['term_months']??0);$p=$this->loans->program($loan['loan_program_id']);if($amount<=0||($p['maximum_amount']>0&&$amount>$p['maximum_amount'])||$term<$p['minimum_term_months']||$term>$p['maximum_term_months'])$this->json('error','Amount or term is outside the program limits.',[],422);try{[$file,$original]=$this->upload();$data=['requested_amount'=>$amount,'principal_amount'=>$amount,'term_months'=>$term,'application_notes'=>sanitize_input($_POST['application_notes']??''),'status'=>'Submitted','admin_remarks'=>null];if($file){$data['requirement_file']=$file;$data['original_name']=$original;}$this->loans->update($id,$data);$this->notes->createForAdmins('Loan application resubmitted','Employee ID '.$emp.' resubmitted loan ID '.$id.'.','info','index.php?page=benefits_loans','benefits',$id);AuditLogger::log('LOAN_APPLICATION_RESUBMITTED','Loans Management','Loan ID '.$id.' resubmitted');$this->json('success','Loan application resubmitted.');}catch(Throwable $e){$this->json('error',$e->getMessage(),[],422);}}
 public function saveProgram(){ $this->post(true);$id=(int)($_POST['id']??0);$name=sanitize_input($_POST['name']??'');$max=(float)($_POST['maximum_amount']??0);$min=(int)($_POST['minimum_term_months']??1);$term=(int)($_POST['maximum_term_months']??36);if(!$name||$max<=0||$min<1||$term<$min)$this->json('error','Enter valid program details and term limits.',[],422);$data=['name'=>$name,'description'=>sanitize_input($_POST['description']??''),'eligibility_rules'=>sanitize_input($_POST['eligibility_rules']??''),'required_documents'=>sanitize_input($_POST['required_documents']??''),'maximum_amount'=>$max,'minimum_term_months'=>$min,'maximum_term_months'=>$term,'interest_rate'=>(float)($_POST['interest_rate']??0),'minimum_tenure_months'=>(int)($_POST['minimum_tenure_months']??0),'eligible_employment_statuses'=>sanitize_input($_POST['eligible_employment_statuses']??'Active,Probationary'),'eligible_department_ids'=>sanitize_input($_POST['eligible_department_ids']??'')];if($id)$this->loans->db->update('loan_programs',$data,'id=?',[$id]);else{$data['created_by']=Auth::user()['id'];$id=$this->loans->db->insert('loan_programs',$data);}AuditLogger::log($id?'LOAN_PROGRAM_SAVED':'LOAN_PROGRAM_CREATED','Loans Management','Loan program '.$name.' saved');$this->json('success','Loan program saved.',['id'=>$id]);}
 public function toggleProgram(){ $this->post(true);$id=(int)($_POST['id']??0);$p=$this->loans->program($id);if(!$p)$this->json('error','Loan program not found.',[],404);$active=$p['is_active']?0:1;$this->loans->db->update('loan_programs',['is_active'=>$active],'id=?',[$id]);AuditLogger::log('LOAN_PROGRAM_STATUS','Loans Management','Loan program ID '.$id.' '.($active?'activated':'deactivated'));$this->json('success','Loan program '.($active?'activated.':'deactivated.'));}
 public function review(){ $this->post(true);$id=(int)($_POST['loan_id']??0);$to=sanitize_input($_POST['status']??'');$loan=$this->loans->details($id);if(!$loan)$this->json('error','Loan not found.',[],404);$map=['Submitted'=>['Under Review','Returned','Approved','Rejected','Cancelled'],'Under Review'=>['Returned','Approved','Rejected'],'Returned'=>['Cancelled'],'Approved'=>['Released','Cancelled'],'Released'=>['Active']];if(!in_array($to,$map[$loan['status']]??[],true))$this->json('error','Invalid loan status transition.',[],422);$remarks=sanitize_input($_POST['admin_remarks']??'');if(in_array($to,['Returned','Rejected'],true)&&!$remarks)$this->json('error','Admin remarks are required.',[],422);$data=['status'=>$to,'admin_remarks'=>$remarks?:$loan['admin_remarks'],'reviewed_by'=>Auth::user()['id'],'reviewed_at'=>date('Y-m-d H:i:s')];if($to==='Approved'){$amount=(float)($_POST['approved_amount']??0);if($amount<=0||$amount>(float)$loan['requested_amount']||($loan['maximum_amount']>0&&$amount>$loan['maximum_amount']))$this->json('error','Approved amount must be positive and within the requested/program limit.',[],422);$rate=(float)$loan['interest_rate'];$total=round($amount+($amount*$rate/100),2);$data+=['approved_amount'=>$amount,'principal_amount'=>$amount,'total_payable'=>$total,'balance_remaining'=>$total,'monthly_deduction'=>round($total/(int)$loan['term_months'],2)];}if($to==='Released'){$date=$_POST['release_date']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$this->json('error','A valid release date is required.',[],422);$data+=['release_date'=>$date,'released_by'=>Auth::user()['id']];}$this->loans->update($id,$data);if($to==='Released')$this->loans->generateSchedule($id,date('Y-m-d',strtotime($data['release_date'].' +1 month')));$this->notes->createForEmployee($loan['employee_id'],'Loan '.$to,'Your '.$loan['loan_type'].' application is now '.$to.'.'.($remarks?' Remarks: '.$remarks:''),in_array($to,['Rejected','Returned'],true)?'warning':'success','index.php?page=benefits_loans','loans',$id);AuditLogger::log('LOAN_STATUS_'.$to,'Loans Management','Loan ID '.$id.' changed from '.$loan['status'].' to '.$to,null,['record_type'=>'loan','record_id'=>$id,'old_value'=>['status'=>$loan['status'],'approved_amount'=>$loan['approved_amount']??null],'new_value'=>['status'=>$to,'approved_amount'=>$data['approved_amount']??($loan['approved_amount']??null),'release_date'=>$data['release_date']??null]]);$this->json('success','Loan status updated to '.$to.'.');}
 public function payment(){ $this->post(true);try{[$balance,$status,$loan]=$this->loans->recordPayment((int)($_POST['loan_id']??0),(float)($_POST['amount']??0),$_POST['payment_date']??date('Y-m-d'),sanitize_input($_POST['payment_method']??'Payroll Deduction'),sanitize_input($_POST['reference_no']??''),Auth::user()['id'],sanitize_input($_POST['remarks']??''));$message='A payment of PHP '.number_format((float)$_POST['amount'],2).' was recorded. Remaining balance: PHP '.number_format($balance,2).'.';$this->notes->createForEmployee($loan['employee_id'],$status==='Paid'?'Loan fully paid':'Loan payment recorded',$message,'success','index.php?page=benefits_loans','loans',$loan['id']);AuditLogger::log('LOAN_PAYMENT_RECORDED','Loans Management','Payment recorded for Loan ID '.$loan['id'].'. Remaining balance: '.$balance,null,['record_type'=>'loan','record_id'=>$loan['id'],'old_value'=>['balance'=>$loan['balance_remaining'],'status'=>$loan['status']],'new_value'=>['payment_amount'=>(float)$_POST['amount'],'balance'=>$balance,'status'=>$status]]);if($status==='Paid')AuditLogger::log('LOAN_FULLY_PAID','Loans Management','Loan ID '.$loan['id'].' fully paid',null,['record_type'=>'loan','record_id'=>$loan['id'],'new_value'=>['balance'=>0,'status'=>'Paid']]);$this->json('success',$message,['balance'=>$balance,'status'=>$status]);}catch(Throwable $e){$this->json('error',$e->getMessage(),[],422);}}
 public function detail(){Auth::requireAuth();$id=(int)($_GET['loan_id']??0);$loan=$this->loans->details($id,Auth::isAdmin()?null:Auth::employeeId());if(!$loan)$this->json('error','Loan record not found or access denied.',[],404);$this->json('success','Loan details loaded.',['loan'=>$loan,'schedule'=>$this->loans->schedule($id),'payments'=>$this->loans->payments($id)]);}
 public function requirement(){Auth::requireAuth();$id=(int)($_GET['loan_id']??0);$loan=$this->loans->details($id,Auth::isAdmin()?null:Auth::employeeId());if(!$loan||!$loan['requirement_file']){http_response_code(404);exit('File not found.');}$path=ROOT_PATH.$loan['requirement_file'];$root=realpath(ROOT_PATH.'uploads/loans');$real=realpath($path);if(!$root||!$real||strpos($real,$root)!==0){http_response_code(403);exit('Forbidden.');}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename='.basename($loan['original_name']?:$real).'');readfile($real);exit;}
}
